import { createHash } from "node:crypto";
import { readFile } from "node:fs/promises";
import path from "node:path";

const root = process.cwd();
const integrity = JSON.parse(await readFile(path.join(root, "protocol/acp/integrity.json"), "utf8"));
for (const schema of integrity.schemas) {
  const bytes = await readFile(path.join(root, "protocol/acp", schema.path));
  const actual = createHash("sha256").update(bytes).digest("hex");
  if (actual !== schema.sha256) throw new Error(`${schema.path} integrity mismatch: ${actual}`);
  const document = JSON.parse(bytes.toString("utf8"));
  if (!document || typeof document !== "object") throw new Error(`${schema.path} is not a schema object`);
}
if (integrity.source.version !== "1.4.0") throw new Error("unexpected TypeScript ACP SDK pin");
if (integrity.java.coordinate !== "com.agentclientprotocol:acp-core:0.16.0") throw new Error("unexpected Java ACP SDK pin");
const [v1Schema, v2Schema] = await Promise.all(integrity.schemas.map(async (schema) =>
  JSON.parse(await readFile(path.join(root, "protocol/acp", schema.path), "utf8"))));
const v1Definitions = Object.keys(v1Schema.$defs ?? v1Schema.definitions ?? {}).sort();
const v2Definitions = Object.keys(v2Schema.$defs ?? v2Schema.definitions ?? {}).sort();
const expectedAdded = v2Definitions.filter((name) => !v1Definitions.includes(name));
const expectedRemoved = v1Definitions.filter((name) => !v2Definitions.includes(name));
const diff = JSON.parse(await readFile(path.join(root, "protocol/acp/generated/v1-to-v2-preview.diff.json"), "utf8"));
if (diff.comparison !== "acp-v1-to-v2-preview"
    || diff.v1DefinitionCount !== v1Definitions.length
    || diff.v2PreviewDefinitionCount !== v2Definitions.length
    || JSON.stringify(diff.addedDefinitions) !== JSON.stringify(expectedAdded)
    || JSON.stringify(diff.removedDefinitions) !== JSON.stringify(expectedRemoved)
    || expectedAdded.length === 0 || expectedRemoved.length === 0) {
  throw new Error("ACP schema diff is stale or does not demonstrate v1/v2-preview isolation");
}
process.stdout.write("ACP schema integrity and v1/v2-preview isolation verified.\n");

