import { readFile } from "node:fs/promises";
import path from "node:path";
import { buildAcpDiff, readAcpInputs, sha256, verifyAcpDiff } from "./lib/acp-contract.mjs";

const root = process.cwd();
const integrity = JSON.parse(await readFile(path.join(root, "protocol/acp/integrity.json"), "utf8"));
const inputs = await readAcpInputs(root);
for (const input of inputs) {
  const entry = integrity.schemas.find((schema) => schema.id === input.id);
  if (!entry || entry.packageSubpath !== input.packageSubpath || entry.path !== input.repositoryPath
      || entry.bytes !== input.sourceBytes.length || entry.sha256 !== sha256(input.sourceBytes)
      || !input.sourceBytes.equals(input.repositoryBytes)) {
    throw new Error(`${input.id} does not match the lock-pinned installed ACP SDK byte-for-byte`);
  }
}
if (integrity.source.package !== "@agentclientprotocol/sdk" || integrity.source.version !== "1.4.0"
    || integrity.source.resolution !== "1.4.0(zod@4.5.4)"
    || integrity.java.coordinate !== "com.agentclientprotocol:acp-core:0.16.0") {
  throw new Error("ACP dependency provenance is inconsistent");
}
const expected = buildAcpDiff(inputs[0].document, inputs[1].document);
const generated = JSON.parse(await readFile(path.join(root, "protocol/acp/generated/v1-to-v2-preview.diff.json"), "utf8"));
if (JSON.stringify(generated) !== JSON.stringify(expected)) throw new Error("ACP schema diff is stale");
const classifications = JSON.parse(await readFile(path.join(root, "protocol/acp/change-classifications.json"), "utf8"));
verifyAcpDiff(generated, classifications);
process.stdout.write("ACP installed-source bytes, full structural diff, and reviewed classifications verified.\n");
